using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:Model"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(chatBuilder => chatBuilder
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

builder.Services.AddSingleton<ResearchTools>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var tools = host.Services.GetRequiredService<ResearchTools>();

var aiTools = new List<AITool>
{
    AIFunctionFactory.Create(tools.WebSearch),
    AIFunctionFactory.Create(tools.SaveNote),
    AIFunctionFactory.Create(tools.GetNotes),
};

var agent = new ChatClientAgent(
    chatClient,
    instructions: "You are a research assistant. Given a topic, use the web_search tool to find "
        + "relevant information. Take notes on key findings using the save_note tool. "
        + "Perform multiple searches to cover different aspects of the topic. "
        + "After researching, retrieve your notes with get_notes and provide a concise summary.",
    name: "ResearchAgent",
    description: "An agent that researches topics using web search and note-taking tools.",
    tools: aiTools);

var topic = args.Length > 0 ? string.Join(' ', args) : "recent advances in quantum computing";
Console.WriteLine($"Researching: {topic}\n");

var session = new ChatClientAgentSession();

var options = new ChatClientAgentRunOptions
{
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
    },
};

var response = await agent.RunAsync(
    $"Research the following topic and summarize your findings: {topic}",
    session,
    options,
    CancellationToken.None);

Console.WriteLine(response.Text);

Console.WriteLine($"\n--- Notes collected ({tools.Notes.Count}) ---");
foreach (var note in tools.Notes)
{
    Console.WriteLine($"  • {note}");
}

/// <summary>Tools available to the research agent.</summary>
public sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    public IReadOnlyList<string> Notes => _notes;

    [Description("Search the web for information on a query. Returns a list of search result snippets.")]
    public IReadOnlyList<string> WebSearch(
        [Description("The search query to look up")] string query)
    {
        // Simulated web search results for demonstration.
        // Replace with a real search API (Bing, Google, Tavily, etc.) in production.
        Console.WriteLine($"  [Tool] Searching: \"{query}\"");
        return
        [
            $"Result 1 for '{query}': Recent research shows significant progress in this area with multiple breakthroughs reported in 2025-2026.",
            $"Result 2 for '{query}': Experts predict major industry impact within the next 3-5 years based on current trajectories.",
            $"Result 3 for '{query}': Key challenges remain around scalability and cost, but new approaches are showing promise.",
        ];
    }

    [Description("Save a research note for later reference. Use this to record key findings.")]
    public string SaveNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Tool] Note saved ({_notes.Count} total)");
        return $"Note saved successfully. You have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes.")]
    public IReadOnlyList<string> GetNotes()
    {
        Console.WriteLine($"  [Tool] Retrieving {_notes.Count} notes");
        return _notes;
    }
}

