var tools = host.Services.GetRequiredService<ResearchTools>();

var agent = new ChatClientAgent(chatClient,
    "ResearchAgent",
    "You are a research assistant. Given a topic, use the web_search tool to find "
    + "relevant information. Take notes on key findings using the save_note tool. "
    + "After researching, provide a concise summary of your findings based on your notes.");

var topic = args.Length > 0 ? string.Join(' ', args) : "recent advances in quantum computing";
Console.WriteLine($"Researching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User,
        $"Research the following topic and summarize your findings: {topic}")
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
    Tools = [.. AIFunctionFactory.Create(tools.WebSearch),
             .. AIFunctionFactory.Create(tools.SaveNote),
             .. AIFunctionFactory.Create(tools.GetNotes)],
    Temperature = 0f,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine();
Console.WriteLine($"\n--- Notes collected ({tools.Notes.Count}) ---");
foreach (var note in tools.Notes)
